import type { MeasuredResult } from '../../types'

/**
 * Re-decodes the final encoded blob using createImageBitmap to extract measured dimensions.
 * Ensures the compliance checklist and UI verify the actual generated bytes and dimensions.
 * Closes the bitmap immediately to release memory.
 */
export async function verifyResult(blob: Blob): Promise<MeasuredResult> {
  let width = 0
  let height = 0

  if (typeof createImageBitmap === 'function') {
    try {
      const bitmap = await createImageBitmap(blob)
      width = bitmap.width
      height = bitmap.height
      if (typeof bitmap.close === 'function') {
        bitmap.close()
      }
    } catch {
      // Fallback
    }
  }

  // Secondary fallback for environments where createImageBitmap has issues
  if ((width === 0 || height === 0) && typeof Image !== 'undefined' && typeof URL !== 'undefined') {
    try {
      await new Promise<void>(resolve => {
        const url = URL.createObjectURL(blob)
        const img = new Image()
        img.onload = () => {
          width = img.naturalWidth || img.width
          height = img.naturalHeight || img.height
          URL.revokeObjectURL(url)
          resolve()
        }
        img.onerror = () => {
          URL.revokeObjectURL(url)
          resolve()
        }
        img.src = url
      })
    } catch {
      // Gracefully continue
    }
  }

  return {
    width,
    height,
    bytes: blob.size,
    mime: blob.type,
  }
}
